{# BAD — `partials/nowhere.j2` is on no search path of any task that renders this file, so
   the render fails on the target host the moment this line is reached. One
   `missing-template` WARNING.

   Measured on ansible-core 2.21.2, rendering this file from a play-level task:

     Task failed: Error rendering template: 'partials/nowhere.j2' not found in search paths:
     '<demo>/templates', '<demo>', '<demo>/templates', '<demo>', '<demo>/templates/templates',
     '<demo>/templates'

   — at task run time, which is why no task in `templates_chain.yml` actually renders it.
   Note the repeats: that is ansible's own list, `[playbook_dir, basedir, dirname(source)]`
   each doubled as `<p>/templates` then `<p>`. #}
{% include "partials/nowhere.j2" %}

{# GOOD — the same absent target with `ignore missing`. Legal by design: ansible renders
   nothing here and the play carries on, so this must stay silent. #}
{% include "partials/nowhere.j2" ignore missing %}

{# GOOD — this one exists. #}
{% include "partials/header.j2" %}

{# T-040 — the root of the include chain. All four target-naming tags, each with a literal
   target, which is exactly what `jinja2.meta.find_referenced_templates` reports:

       extends base.conf.j2 · import macros.j2 · from macros.j2 · include partials/header.j2
       · include optional.conf.j2

   Ansible never parses this file at playbook-parse time; a broken tag here is a run-time
   failure on the target host. `broken.conf.j2` is that case. #}
{% extends "base.conf.j2" %}
{% import "macros.j2" as m %}
{% from "macros.j2" import listen_line %}

{% block header %}
{% include "partials/header.j2" %}
{% endblock %}

{% block body %}
{{ listen_line(app_port | default(8080)) }}
{{ m.upstream('web') }}
{% include "optional.conf.j2" %}
{% endblock %}

#jinja2: block_start_string:"<%", block_end_string:"%>", variable_start_string:"[%", variable_end_string:"%]"
{# GOOD — the `#jinja2:` header replaces the delimiters for this file only. Ansible reads it
   (`_jinja_bits.py:76,162-192`); it must be the very first byte, and it beats anything the
   `template:` module passes. Both measured on ansible-core 2.21.2. #}
<% include "partials/header.j2" %>
server [% inventory_hostname %];

{# Measured, and not obvious: the overridden delimiters belong to the whole render, not to
   this file. `partials/header.j2` is written with the default `{{ }}` and is pulled in here,
   so its `{{ inventory_hostname }}` comes out LITERAL — `# rendered for {{ inventory_hostname }}`
   — while `[% inventory_hostname %]` above renders. One template, two delimiter sets, and
   only the includer's win. #}

{# NO HINT — with the block delimiters moved, this is ordinary text, and the file renders it
   verbatim. Read with the default `{% %}` we would call `notatag` an unknown tag and put a
   red squiggle on a template that works. That false positive is the reason the header is
   read at all. #}
{% notatag %}

{# T-040 — the parent of the chain. `app.conf.j2` extends this file, so this is the template
   that produces the output; the child only fills the blocks. #}
# {{ app_name | default('demo') }} — generated by ansible, do not edit
{% block header %}{% endblock %}
[server]
port = {{ app_port | default(8080) }}
{% block body %}{% endblock %}

{# T-040 — the play-level `shared.j2`. Two roles have a file of the same name; this is the
   one a play-level task gets. #}
# shared: play-level templates/

{# T-040 — the import target. `import` binds this whole file as a namespace and `from` binds
   one name out of it; both spellings name the same file and both are references. #}
{% macro upstream(group) %}upstream {{ group }} { server 127.0.0.1; }{% endmacro %}
{% macro listen_line(port) %}listen {{ port }};{% endmacro %}

{# T-040 — every way of writing an include that is not one plain literal. Each comment says
   what `find_referenced_templates` reports, which is what this project must report too. #}

{# NAMES BOTH: a list is not a dynamic name. Jinja tries the entries in order and renders the
   first that exists; upstream reports every entry, so both are references. #}
{% include ["partials/site.j2", "partials/header.j2"] %}

{# NAMES ONE: `ignore missing` makes an absent target legal, and it is still a reference —
   the modifier changes what happens at render, not what the tag points at. #}
{% include "partials/absent.j2" ignore missing %}

{# NAMES NOTHING: the target is a runtime value. There is no file to judge, so the answer is
   silence rather than a guess — the standing trade everywhere in this codebase. #}
{% include tuning_file %}

{# NAMES NOTHING: `raw` is a lexer state, so its body is literal text and not a tag at all. #}
{% raw %}{% include "partials/header.j2" %}{% endraw %}

{# NAMES NOTHING, and this line is why the lexer has a comment state:
   {% include "partials/header.j2" %} #}

{# ONE TAG, NOT TWO: the `%}` is inside a string, so it does not end the tag. A `{%`-search
   splits this line and reports the rest of it as template data. #}
{% if app_env == '%}' %}# unreachable unless app_env really is that string{% endif %}

{# BAD — a template that cannot render. `Encountered unknown tag 'forr'`, from jinja2 3.1.6
   and from us; one `template-syntax` ERROR on the line below.

   No task renders this file, and that is the point. Measured on ansible-core 2.21.2: a
   playbook with this file sitting in `templates/` runs `ok`, because a template is not
   parsed until the task that renders it runs on the target. The runtime does report this
   — at deploy, on the managed host. Here it is a squiggle while you type. #}
{% forr host in groups['web'] %}
server {{ host }};
{% endforr %}
